import HersheySans1 from "./data/HersheySans1.json";
import HersheySansMed from "./data/HersheySansMed.json";
import HersheySerifMed from "./data/HersheySerifMed.json";
import HersheyScript1 from "./data/HersheyScript1.json";

/**
 * A single-line (stroke) font: every glyph is an open centre-line path that a
 * pen plotter draws exactly once, instead of an outline it would trace around.
 *
 * Coordinates are in font units, y pointing up from the baseline. Paths only
 * use absolute M/L/C/Z commands. Generated by scripts/build-single-line-fonts.mjs.
 */
export interface SingleLineFont {
    id: string;
    name: string;
    unitsPerEm: number;
    ascent: number;
    descent: number;
    /** Advance width used for characters the font has no glyph for. */
    advance: number;
    /** Character -> [advance width, path data]. Blank glyphs have no path. */
    glyphs: Record<string, [number, string?]>;
}

/** Bundled fonts in picker order, with the short label shown in the UI. */
const FONT_LIST = (
    [
        [HersheySans1, "Sans"],
        [HersheySansMed, "Sans Medium"],
        [HersheySerifMed, "Serif"],
        [HersheyScript1, "Script"],
    ] as unknown as [SingleLineFont, string][]
).map(([font, label]) => ({ ...font, label }));

export const DEFAULT_FONT_ID = "HersheySans1";

/** Fabric class type of SingleLineText; lives here so UI code can check it without importing Fabric. */
export const SINGLE_LINE_TEXT_TYPE = "SingleLineText";

export const SINGLE_LINE_FONTS: ReadonlyArray<{ id: string; label: string }> =
    FONT_LIST.map(({ id, label }) => ({ id, label }));

const FONTS = new Map(FONT_LIST.map((font) => [font.id, font]));

export function hasSingleLineFont(id: string | undefined): boolean {
    return !!id && FONTS.has(id);
}

/** Falls back to the default font, so unknown names never drop text. */
export function getSingleLineFont(id: string | undefined): SingleLineFont {
    return FONTS.get(id ?? "") ?? FONTS.get(DEFAULT_FONT_ID)!;
}
